import pyomo.environ as pyo

DATA = {
    "types": ["X1", "X2", "X3"],
    "cost": {"X1": 5, "X2": 8, "X3": 6},
    "capacity_max": 1000,
    "balance_coef_X1": 2,
    "balance_coef_X2": 3,
    "balance_min": 200,
    "portfolio_coef_X3": 4,
    "portfolio_coef_X1": 1,
    "portfolio_max": 500,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.TYPES = pyo.Set(initialize=d["types"])

    model.shipments = pyo.Var(
        model.TYPES,
        domain=pyo.NonNegativeIntegers,
    )

    def objective_rule(m):
        return sum(d["cost"][t] * m.shipments[t] for t in m.TYPES)

    model.obj = pyo.Objective(rule=objective_rule, sense=pyo.minimize)

    def capacity_rule(m):
        return sum(m.shipments[t] for t in m.TYPES) <= d["capacity_max"]

    model.capacity = pyo.Constraint(rule=capacity_rule)

    def balance_rule(m):
        return (
            d["balance_coef_X1"] * m.shipments["X1"]
            - d["balance_coef_X2"] * m.shipments["X2"]
            >= d["balance_min"]
        )

    model.balance = pyo.Constraint(rule=balance_rule)

    def portfolio_rule(m):
        return (
            d["portfolio_coef_X3"] * m.shipments["X3"]
            - d["portfolio_coef_X1"] * m.shipments["X1"]
            <= d["portfolio_max"]
        )

    model.portfolio = pyo.Constraint(rule=portfolio_rule)

    return model


